class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        int LIMIT = 1024;
        vector<unordered_map<int, int>> groups(k);
        vector<int> size(k, 0);
        for (int i = 0; i < nums.size(); i++) {
            groups[i % k][nums[i]]++;
            size[i % k]++;
        }
        vector<int> dp(LIMIT, 1e9);
        dp[0] = 0;
        for (int i = 0; i < k; i++) {
            int minPrev = *min_element(dp.begin(), dp.end());
            vector<int> next_dp(LIMIT, minPrev + size[i]);
            for (int prevVal = 0; prevVal < LIMIT; prevVal++) {
                if (dp[prevVal] == 1e9) continue;
                for (const auto& [val, cnt] : groups[i]) {
                    int newVal = prevVal ^ val;
                    next_dp[newVal] = min(next_dp[newVal], dp[prevVal] + size[i] - cnt);
                }
            }
            dp = std::move(next_dp);
        }
        return dp[0];
    }
};

class Solution {
    public int minChanges(int[] nums, int k) {
        int LIMIT = 1024;
        List<Map<Integer, Integer>> groups = new ArrayList<>();
        int[] size = new int[k];
        for (int i = 0; i < k; i++) groups.add(new HashMap<>());
        for (int i = 0; i < nums.length; i++) {
            groups.get(i % k).put(nums[i], groups.get(i % k).getOrDefault(nums[i], 0) + 1);
            size[i % k]++;
        }
        int[] dp = new int[LIMIT];
        Arrays.fill(dp, 1_000_000);
        dp[0] = 0;
        for (int i = 0; i < k; i++) {
            int minPrev = Integer.MAX_VALUE;
            for (int v : dp) minPrev = Math.min(minPrev, v);
            int[] next = new int[LIMIT];
            Arrays.fill(next, minPrev + size[i]);
            for (int prevVal = 0; prevVal < LIMIT; prevVal++) {
                if (dp[prevVal] == 1_000_000) continue;
                for (var entry : groups.get(i).entrySet()) {
                    int val = entry.getKey(), cnt = entry.getValue();
                    int newVal = prevVal ^ val;
                    next[newVal] = Math.min(next[newVal], dp[prevVal] + size[i] - cnt);
                }
            }
            dp = next;
        }
        return dp[0];
    }
}

var minChanges = function(nums, k) {
    const LIMIT = 1024;
    const groups = Array.from({ length: k }, () => new Map());
    const size = new Array(k).fill(0);
    for (let i = 0; i < nums.length; i++) {
        const grp = groups[i % k];
        grp.set(nums[i], (grp.get(nums[i]) || 0) + 1);
        size[i % k]++;
    }
    let dp = new Int32Array(LIMIT).fill(1e9);
    dp[0] = 0;
    for (let i = 0; i < k; i++) {
        let minPrev = 1e9;
        for (let v = 0; v < LIMIT; v++) {
            if (dp[v] < minPrev) minPrev = dp[v];
        }
        const next = new Int32Array(LIMIT).fill(minPrev + size[i]);
        for (let prevVal = 0; prevVal < LIMIT; prevVal++) {
            if (dp[prevVal] === 1e9) continue;
            for (const [val, cnt] of groups[i]) {
                const newVal = prevVal ^ val;
                const cost = dp[prevVal] + size[i] - cnt;
                if (cost < next[newVal]) next[newVal] = cost;
            }
        }
        dp = next;
    }
    return dp[0];
};
